begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_worker;
set local search_path=extensions,pg_catalog;
select no_plan();
select ok(to_regprocedure('internal.pause_worker_admission(text,text,bigint,text)') is not null,'private graceful pause boundary exists');
select ok(to_regprocedure('internal.resume_worker_admission(text,text,bigint,bigint,text)') is not null,'private generation resume boundary exists');
select ok(exists(select 1 from information_schema.columns where table_schema='internal' and table_name='worker_dispatch_control' and column_name='last_completed_wake_id'),'bounded last completed wake supports original duplicate proof');
select ok(not has_function_privilege('cuevo_worker','internal.pause_worker_admission(text,text,bigint,text)','EXECUTE'),'worker cannot pause admission');
select ok(not has_function_privilege('cuevo_api','internal.resume_worker_admission(text,text,bigint,bigint,text)','EXECUTE'),'API cannot choose execution generation');
select ok(not has_function_privilege('authenticated','internal.pause_worker_admission(text,text,bigint,text)','EXECUTE'),'browser cannot pause worker');
select ok(not has_function_privilege('service_role','internal.resume_worker_admission(text,text,bigint,bigint,text)','EXECUTE'),'service role cannot resume private worker');
select ok(not has_function_privilege('cuevo_worker','internal.claim_posthog_delivery(integer,integer,integer)','EXECUTE'),'superseded analytics overload retains denied runtime grant');

-- Fixed rollback fixture performs no network delivery and preserves all source history.
create or replace function internal.send_worker_wake(target_wake uuid,target_endpoint text,target_secret_name text)returns bigint language sql as $$select 221::bigint$$;
update internal.worker_dispatch_control set enabled=true,endpoint='https://worker.example.test/functions/v1/cuevo-worker',vault_secret_name='worker-rollout-fixture',state='REQUESTED',wake_id='22100000-0000-4000-8000-000000000001',lease_expires_at=clock_timestamp()+interval'60 seconds',network_request_id=221,execution_generation=1,admission_paused=false,rollout_operation_sha256=null where singleton;
select is(internal.pause_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',2,repeat('a',64)),false,'wrong previous generation cannot pause');
select is(internal.pause_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',1,repeat('a',64)),true,'exact owned generation pauses');
select is((select wake_id from internal.worker_dispatch_control where singleton),'22100000-0000-4000-8000-000000000001'::uuid,'pause preserves current wake');
select is((select vault_secret_name from internal.worker_dispatch_control where singleton),'worker-rollout-fixture','pause preserves original key reference');
select is((select enabled from internal.worker_dispatch_control where singleton),true,'pause retains dispatch configuration');
select is(internal.request_worker_wake(),false,'pause denies committed wake and Cron hints');
select is((select count(*) from internal.claim_posthog_delivery(1,30,1)),0::bigint,'superseded owner analytics call cannot bypass admission pause');
select ok(pg_get_functiondef('internal.claim_posthog_delivery(integer,integer,integer)'::regprocedure) like '%control.admission_paused or control.execution_generation is not null%','superseded analytics entry retains original behavior behind null-generation admission');
set local role cuevo_worker;
select is(internal.begin_worker_wake('22100000-0000-4000-8000-000000000001',1),false,'pause denies new signed invocation');
select is((select count(*) from internal.claim_outbox(1,30,1)),0::bigint,'pause denies generation-bound domain claims');
select is((select count(*) from internal.claim_outbox(1,30)),0::bigint,'legacy claim cannot bypass pause');
reset role;

update internal.worker_dispatch_control set state='RUNNING' where singleton;
set local role cuevo_worker;
select is(internal.finish_worker_wake('22100000-0000-4000-8000-000000000001','COMPLETED',1),false,'owner SET ROLE cannot impersonate restricted worker completion');
reset role;
select is((select state from internal.worker_dispatch_control where singleton),'RUNNING','denied owner finish preserves original running wake');
update internal.worker_dispatch_control set lease_expires_at=clock_timestamp()-interval'1 second' where singleton;
select is(internal.resume_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',1,2,repeat('b',64)),false,'foreign operation cannot resume');
select is(internal.resume_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',1,3,repeat('a',64)),false,'generation cannot skip');
select is(internal.resume_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',1,2,repeat('a',64)),true,'drained exact owner enables the next generation');
select is((select execution_generation from internal.worker_dispatch_control where singleton),2::bigint,'generation increments once');
select is((select admission_paused from internal.worker_dispatch_control where singleton),false,'resume opens admission');
select is(internal.pause_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',2,repeat('c',64)),true,'next owned generation can pause again');
update internal.worker_dispatch_control set execution_generation=null where singleton;
select is(internal.resume_worker_admission('https://worker.example.test/functions/v1/cuevo-worker','worker-rollout-fixture',null,1,repeat('c',64)),true,'initial exact owned legacy pause can enable generation one');
update internal.worker_dispatch_control set execution_generation=2 where singleton;
set local role cuevo_worker;
select is(internal.begin_worker_wake('22100000-0000-4000-8000-000000000001',1),false,'stale worker generation cannot admit');
select is((select count(*) from internal.claim_outbox(1,30)),0::bigint,'legacy claim cannot bypass configured generation');
reset role;
select*from finish();
rollback;
